#include <stdio.h>

int parent[100005];
int rank[100005];
int a[100005], b[100005], t[100005];

void init(int n) {
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void union_set(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rank[x] < rank[y]) {
        parent[x] = y;
    } else if (rank[x] > rank[y]) {
        parent[y] = x;
    } else {
        parent[y] = x;
        rank[x]++;
    }
}

int main(void) {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    init(N);

    // Primeira passada: processa hidrovias e verifica se formam ciclo
    for (int i = 0; i < M; i++) {
        scanf("%d %d %d", &a[i], &b[i], &t[i]);
        if (t[i] == 1) {
            if (find(a[i]) == find(b[i])) {
                printf("N\n");
                return 0;
            }
            union_set(a[i], b[i]);
        }
    }

    // Segunda passada: une as rodovias para obter as componentes conexas do grafo completo
    for (int i = 0; i < M; i++) {
        if (t[i] == 2) {
            union_set(a[i], b[i]);
        }
    }

    // Conta o número de componentes conexas
    int CC = 0;
    for (int i = 1; i <= N; i++) {
        if (find(i) == i) {
            CC++;
        }
    }

    // Mínimo de rodovias a remover para tornar o grafo uma floresta
    int min_del = M - N + CC;

    if (min_del <= K) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
